const html = $input.first().json.data || $input.first().json.body || '';
const webhook = $('Blog publish webhook').first().json.body;
const title = (webhook.title || '').trim();
const url = (webhook.url || webhook.link || '').trim();
const locale = (webhook.locale || 'en').trim();
const text = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').substring(0, 3000);
return [{ json: { title, url, locale, text } }];

const raw = $input.first().json;
const list = Array.isArray(raw) ? raw : (raw.integrations || []);
const allow = ['x', 'linkedin', 'linkedin-page', 'facebook', 'instagram', 'threads', 'bluesky'];
const channels = list.filter(i => allow.includes(i.identifier) && !i.disabled);
const extract = $('Extract text').first().json;
if (!channels.length) return [{ json: { skip: true, reason: 'no_channels' } }];
return channels.map(c => ({ json: { ...extract, channelId: c.id, platform: c.identifier } }));

const d = $input.first().json;
if (d.skip) return [{ json: { skip: true, reason: d.reason } }];
const apiUrl = $env.AI_API_URL || 'https://integrate.api.nvidia.com/v1/chat/completions';
const apiKey = $env.NVIDIA_API_KEY;
const model = $env.AI_MODEL || 'nvidia/nemotron-3.5-lightning-30b-a3b';

const rules = {
  x: 'Max 280 chars. Punchy, 1-2 hashtags.',
  linkedin: '2-3 paragraphs, professional tone, 3-5 hashtags. Include a call-to-action.',
  'linkedin-page': '2-3 paragraphs, professional tone, 3-5 hashtags. Include a call-to-action.',
  instagram: 'Casual, engaging, use emojis, 5-10 hashtags at end.',
  threads: 'Casual, engaging, use emojis, 5-10 hashtags at end.',
  bluesky: 'Max 300 chars, conversational, 1-2 hashtags.',
  facebook: 'Medium length, engaging, 2-3 hashtags.'
};
const lang = d.locale === 'el' ? 'Greek' : 'English';
const rule = rules[d.platform] || 'Medium length, engaging, 2-3 hashtags.';

const body = {
  model,
  max_tokens: 300,
  temperature: 0.7,
  messages: [
    { role: 'system', content: 'You are a social media copywriter for cloudless.gr, a cloud services company in Greece. Output ONLY the post text, no explanation or preamble.' },
    { role: 'user', content: `Write a ${d.platform} post promoting this blog article. Title: "${d.title}". Content summary: ${d.text.substring(0, 1500)}\n\nRules:\n- ${rule}\n- Language: ${lang}\n- Do NOT include the URL (it is added automatically).` }
  ]
};

const resp = await fetch(apiUrl, {
  method: 'POST',
  headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
  body: JSON.stringify(body)
});
const result = await resp.json();
if (!resp.ok) return [{ json: { error: true, status: resp.status, detail: result } }];

const caption = (result.choices?.[0]?.message?.content || '').trim();
const utm = d.url + (d.url.includes('?') ? '&' : '?') + 'utm_source=postiz&utm_medium=social&utm_campaign=blog&utm_content=' + d.platform;
const fullCaption = caption + '\n\n' + utm;

return [{ json: { caption: fullCaption, channelId: d.channelId, platform: d.platform, title: d.title } }];
